  Edge() {};

  Edge(int _from, int _to, int _flow, int _cost) 
    : from(_from), to(_to), flow(_flow), cost(_cost) {};
};

vector<Edge> edges;
const int MAXN = 1e6 + 7;
vector<int> adj[MAXN];

ll totalCost = 0;
ll dist[MAXN];
int parent[MAXN];
int parentEdge[MAXN];
int inQueue[MAXN];

int s = MAXN - 2;
int t = MAXN - 1;

int residual(int eIdx) {
  return edges[eIdx].to - edges[eIdx].flow;
}

void shortestPath() {
  for (int i = 0; i < MAXN; i++) {
    dist[i] = INF64;
    parent[i] = -1;
    parentEdge[i] = -1;
    inQueue[i] = 0;
  }
  dist[s] = 0;
  queue<int> q;
  q.push(s);
  inQueue[s] = 1;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    inQueue[u] = 0;
    for (auto eIdx : adj[u]) {
      if (!residual(eIdx)) continue;
      int cst = edges[eIdx].cost;
