          q.push(v);
        }
      }
    }
  }
}

void findAugment() {
  shortestPath();
  int cur = t;
  while (cur != s) {
    edges[parentEdge[cur]].flow++;
    edges[parentEdge[cur] ^ 1].flow--;
    cur = parent[cur];
  }
  totalCost += dist[t];
}

void createEdge(int u, int v, int cap, int cst) {
  adj[u].push_back(edges.size());
  edges.emplace_back(u, v, 0, cst);
  adj[v].push_back(edges.size());
  edges.emplace_back(v, u, cap, -cst);
}

int n, m, k, c, d;
const int T = 101;

void buildGraph() {
  scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
  for (int i = 0; i < k; i++) {
    int x; scanf("%d", &x);
    --x;
    createEdge(s, x, 1, 0);
  }
  for (int i = 0; i < T; i++) {
