import java.util.*;

public class Main {
    static class Edge {
        int from, to, flow, cost;
        Edge(int from, int to, int flow, int cost) {
            this.from = from;
            this.to = to;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static final long INF64 = (long)1e18;
    static final int MAXN = 1000007;
    static List<Integer>[] adj = new ArrayList[MAXN];
    static List<Edge> edges = new ArrayList<>();
    static long totalCost = 0;
    static long[] dist = new long[MAXN];
    static int[] parent = new int[MAXN];
    static int[] parentEdge = new int[MAXN];
    static int[] inQueue = new int[MAXN];

    static int s = MAXN - 2;
    static int t = MAXN - 1;
    static int n, m, k, c, d;
    static final int T = 101;

    static int residual(int eIdx) {
        return edges.get(eIdx).to - edges.get(eIdx).flow;
    }

    static void shortestPath() {
        Arrays.fill(dist, INF64);
        Arrays.fill(parent, -1);
        Arrays.fill(parentEdge, -1);
        Arrays.fill(inQueue, 0);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        inQueue[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inQueue[u] = 0;
            for (int eIdx : adj[u]) {
                if (residual(eIdx) == 0) continue;
                int cst = edges.get(eIdx).cost;
                int v = edges.get(eIdx).from;
                if (dist[v] > dist[u] + cst) {
                    dist[v] = dist[u] + cst;
                    parent[v] = u;
                    parentEdge[v] = eIdx;
                    if (inQueue[v] == 0) {
                        inQueue[v] = 1;
                        q.offer(v);
                    }
                }
            }
        }
    }

    static void findAugment() {
        shortestPath();
        int cur = t;
        while (cur != s) {
            edges.get(parentEdge[cur]).flow++;
            edges.get(parentEdge[cur] ^ 1).flow--;
            cur = parent[cur];
        }
        totalCost += dist[t];
    }

    static void createEdge(int u, int v, int cap, int cst) {
        if (adj[u] == null) adj[u] = new ArrayList<>();
        adj[u].add(edges.size());
        edges.add(new Edge(u, v, 0, cst));
        if (adj[v] == null) adj[v] = new ArrayList<>();
        adj[v].add(edges.size());
        edges.add(new Edge(v, u, cap, -cst));
    }

    static void buildGraph() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            x--;
            createEdge(s, x, 1, 0);
        }

        for (int i = 0; i < T; i++) {
            createEdge(i * n, t, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            x--;
            y--;
            for (int tIdx = 0; tIdx < T - 1; tIdx++) {
                for (int j = 0; j < k; j++) {
                    createEdge(x + tIdx * n, y + tIdx * n + n, 1, d * (j * 2 + 1));
                }
            }
            for (int tIdx = 0; tIdx < T - 1; tIdx++) {
                for (int j = 0; j < k; j++) {
                    createEdge(y + tIdx * n, x + tIdx * n + n, 1, d * (j * 2 + 1));
                }
            }
        }
        sc.close();
    }

    static void solve() {
        for (int i = 0; i < n; i++) {
            for (int tIdx = 0; tIdx < T - 1; tIdx++) {
                createEdge(i + tIdx * n, i + tIdx * n + n, k, 0);
            }
        }
        for (int i = 0; i < k; i++) {
            findAugment();
        }
        System.out.println(totalCost);
    }

    public static void main(String[] args) {
        buildGraph();
        solve();
    }
}
